/bin/bash -c "python - <<'PY'
import cv2, numpy as np
im=cv2.imread('first_frame.png')
g=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY)
crop=g[180:280,140:250]
for p1 in [30,50,80,100]:
 for p2 in [10,15,20,25]:
  cs=cv2.HoughCircles(crop,cv2.HOUGH_GRADIENT,dp=1,minDist=20,param1=p1,param2=p2,minRadius=25,maxRadius=45)
  if cs is not None: print(p1,p2,np.round(cs[0],2))
PY"

